// Account Number: "IB" + 10 digits, the last a Luhn check digit.
// Generated by the database (see supabase/migrations); the app only formats
// and validates it (e.g. when an RM types one in).

/** "IB4821593067" -> "IB 4821 593 067" */
export function formatAccountNumber(acct: string): string {
  const m = /^IB(\d{4})(\d{3})(\d{3})$/.exec(acct);
  return m ? `IB ${m[1]} ${m[2]} ${m[3]}` : acct;
}

export function luhnCheckDigit(payload: string): number {
  let total = 0;
  for (let i = 0; i < payload.length; i++) {
    let d = Number(payload[payload.length - 1 - i]);
    if (i % 2 === 0) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    total += d;
  }
  return (10 - (total % 10)) % 10;
}

/** Accepts "IB 4821 593 067", "ib4821593067", etc. */
export function isValidAccountNumber(input: string): boolean {
  const acct = input.replace(/\s/g, "").toUpperCase();
  if (!/^IB\d{10}$/.test(acct)) return false;
  return luhnCheckDigit(acct.slice(2, 11)) === Number(acct[11]);
}
